export type ProjectStatus = 'draft' | 'active' | 'paused' | 'completed' | 'archived'

export type ProjectRole = 'owner' | 'admin' | 'member' | 'viewer' | 'collaborator'

export type Project = {
  id: string
  tenantId: string
  workplaceId: string | null
  ownerCentralId: string
  title: string
  description?: string | null
  color?: string | null
  icon?: string | null
  status: ProjectStatus
  isFavorite?: boolean
  createdAt: string
  updatedAt: string
  // UI-derived / optional
  roleForCurrentUser?: ProjectRole
  objectivesCount?: number
  membersCount?: number
  fundBalance?: number
  tags?: string[]
  startDate?: string
  endDate?: string
  templateId?: string
}

export type ProjectMember = {
  userId: string
  projectId: string
  role: 'owner' | 'admin' | 'member' | 'viewer'
  displayName: string
  avatarUrl?: string
  joinedAt: string
}

export type ProjectTemplate = {
  id: string
  title: string
  description: string
  type: 'public' | 'private' | 'paid'
  tenantId?: string
  tags: string[]
  objectivesCount: number
  previewUrl?: string
}
